effect.shader:
const float PI = 3.14159265358979323846;

float luminance(vec3 c){
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

vec3 srgbToLinear(vec3 c){
  vec3 cut = step(vec3(0.04045), c);
  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), cut);
}

vec3 linearToSrgb(vec3 c){
  c = max(c, vec3(0.0));
  vec3 cut = step(vec3(0.0031308), c);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, cut);
}

float hash11(float n){
  return fract(sin(n) * 43758.5453123);
}

float hash21(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec3 blendOverlay(vec3 base, vec3 blend){
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, base));
}

vec3 blendSoftLight(vec3 base, vec3 blend){
  vec3 low  = 2.0 * base * blend + base * base * (1.0 - 2.0 * blend);
  vec3 high = sqrt(base) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend);
  return mix(low, high, step(0.5, blend));
}

vec3 blendHardLight(vec3 base, vec3 blend){
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, blend));
}

float toneCurve(float v, float lift, float gain, float gam){
  v = clamp(v, 0.0, 1.0);
  v = v * (gain - lift) + lift;
  v = pow(max(v, 0.0001), 1.0 / max(gam, 0.001));
  return clamp(v, 0.0, 1.0);
}

float filmContrast(float lum, float shadowC, float highlightC, float midC, float bPoint, float wPoint){
  lum = (lum - bPoint) / max(wPoint - bPoint, 0.0001);
  lum = clamp(lum, 0.0, 1.0);
  float shadowMask    = smoothstep(0.4, 0.0, lum);
  float highlightMask = smoothstep(0.6, 1.0, lum);
  float midMask       = 1.0 - shadowMask - highlightMask;
  midMask = clamp(midMask, 0.0, 1.0);
  float contMult = shadowMask * shadowC + highlightMask * highlightC + midMask * midC;
  lum = (lum - 0.5) * contMult + 0.5;
  return clamp(lum, 0.0, 1.0);
}

vec3 applyDesat(vec3 col, float lum, float shadowD, float midD, float highlightD){
  float shadowMask    = smoothstep(0.4, 0.0, lum);
  float highlightMask = smoothstep(0.6, 1.0, lum);
  float midMask       = clamp(1.0 - shadowMask - highlightMask, 0.0, 1.0);
  float desatAmt = shadowMask * shadowD + midMask * midD + highlightMask * highlightD;
  return mix(col, vec3(lum), desatAmt);
}

float filmGrain(vec2 uv, float time, float speed, float size){
  float t = floor(time * speed);
  vec2 scaledUV = uv * (500.0 / max(size, 0.1));
  float n = hash21(scaledUV + vec2(t * 1.7, t * 3.1));
  float n2 = hash21(scaledUV * 1.3 + vec2(t * 2.3, t * 1.5));
  return (n + n2) * 0.5;
}

vec3 applyHalation(vec3 col, float lum, float strength, float threshold, vec3 hColor){
  float halMask = smoothstep(threshold - 0.1, threshold + 0.1, lum);
  vec3 halGlow = hColor * halMask * strength;
  return clamp(col + halGlow, 0.0, 1.0);
}

vec3 applyTint(vec3 col, float lum, vec3 sTint, float sStr, vec3 hTint, float hStr){
  float shadowMask    = smoothstep(0.4, 0.0, lum);
  float highlightMask = smoothstep(0.6, 1.0, lum);
  col = mix(col, col * sTint * 2.0, shadowMask * sStr);
  col = mix(col, col * hTint * 2.0, highlightMask * hStr);
  return clamp(col, 0.0, 1.0);
}

void main(){

  vec2 uv = acScreenNorm;
  float t = acTime;

  vec4 src = texture2DCv(inputImg.texture, uv);
  vec3 col = src.rgb;

  float lum = luminance(srgbToLinear(col));

  float lumContrast = filmContrast(
    lum,
    shadowContrast, highlightContrast, midContrast,
    blackPoint, whitePoint
  );

  lumContrast = toneCurve(lumContrast, liftShadows, gainHighlights, gamma);

  vec3 bwHigh = vec3(lumContrast);

  vec3 colDesat = applyDesat(col, lum, shadowDesat, midDesat, highlightDesat);

  vec3 blended;
  float bmf = float(blendMode);
  if(bmf < 1.5){
    blended = blendOverlay(colDesat, bwHigh);
  } else if(bmf < 2.5){
    blended = blendSoftLight(colDesat, bwHigh);
  } else {
    blended = blendHardLight(colDesat, bwHigh);
  }

  vec3 result = mix(colDesat, blended, bypassStrength);

  float lumResult = luminance(srgbToLinear(result));

  if(halationEnable){
    result = applyHalation(result, lumResult, halationStrength, halationThreshold, halationColor.rgb);
  }

  result = applyTint(result, lumResult, shadowTint.rgb, shadowTintStr, highlightTint.rgb, highlightTintStr);

  if(grainEnable){
    float grain = filmGrain(uv, t, grainSpeed, grainSize);
    float grainMask = 1.0 - abs(lumResult - 0.5) * 0.5;
    result += (grain - 0.5) * grainStrength * grainMask;
    result = clamp(result, 0.0, 1.0);
  }

  result = mix(col, result, overallStrength);

  if(bwPreview){
    float bwLum = filmContrast(
      luminance(srgbToLinear(col)),
      shadowContrast, highlightContrast, midContrast,
      blackPoint, whitePoint
    );
    bwLum = toneCurve(bwLum, liftShadows, gainHighlights, gamma);
    gl_FragColor = vec4(vec3(bwLum), src.a);
    return;
  }

  gl_FragColor = vec4(result, src.a);
}
